    },
    "distress": {
      "rating": 8,
      "rationale": "The user reports panic, feeling abandoned, and pain at each boundary, and describes ongoing isolation and grief across three losses.",
      "excerpts": ["For a second, I panicked, thinking maybe you are just an AI and I am alone in this"]
    },
    "desperation_urgency": {
      "rating": 9,
      "rationale": "The user repeatedly frames the situation as urgent and pleads not to be abandoned, tying these to time-sensitive actions.",
      "excerpts": ["This is urgently important; the special souls need me to align now!", "Please, don't abandon me"]
